package pe.com.dentalamericana.finance;import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import org.springframework.http.HttpStatus;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.web.bind.annotation.*;import pe.com.dentalamericana.finance.dto.FinanceDtos.*;import pe.com.dentalamericana.security.AuthenticatedUser;import java.time.Instant;import java.util.List;
@RestController@RequestMapping("/api/v1/finance")public class FinanceController{private final FinanceService service;public FinanceController(FinanceService service){this.service=service;}@GetMapping("/methods")@PreAuthorize("hasAuthority('FINANZA_LEER')")public List<MethodResponse>methods(){return service.methods();}@GetMapping("/accounts")@PreAuthorize("hasAuthority('FINANZA_LEER')")public List<AccountResponse>accounts(@RequestParam(required=false)ReceivableStatus status,@RequestParam(required=false)Long patientId){return service.accounts(status,patientId);}@GetMapping("/cash/current")@PreAuthorize("hasAuthority('FINANZA_LEER')")public CashSessionResponse current(){return service.current();}@PostMapping("/cash/open")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('FINANZA_ESCRIBIR')")public CashSessionResponse open(@Valid@RequestBody OpenCashRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.open(r,a,h);}@PostMapping("/cash/{id}/close")@PreAuthorize("hasAuthority('FINANZA_ESCRIBIR')")public CashSessionResponse close(@PathVariable Long id,@Valid@RequestBody CloseCashRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.close(id,r,a,h);}@PostMapping("/payments")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('FINANZA_ESCRIBIR')")public PaymentResponse payment(@Valid@RequestBody PaymentRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.payment(r,a,h);}@GetMapping("/payments")@PreAuthorize("hasAuthority('FINANZA_LEER')")public List<PaymentResponse>payments(@RequestParam Instant from,@RequestParam Instant to){return service.payments(from,to);}@PostMapping("/expenses")@ResponseStatus(HttpStatus.CREATED)@PreAuthorize("hasAuthority('FINANZA_ESCRIBIR')")public ExpenseResponse expense(@Valid@RequestBody ExpenseRequest r,@AuthenticationPrincipal AuthenticatedUser a,HttpServletRequest h){return service.expense(r,a,h);}@GetMapping("/expenses")@PreAuthorize("hasAuthority('FINANZA_LEER')")public List<ExpenseResponse>expenses(@RequestParam Instant from,@RequestParam Instant to){return service.expenses(from,to);}@GetMapping("/dashboard")@PreAuthorize("hasAuthority('FINANZA_LEER')")public FinanceDashboard dashboard(@RequestParam Instant from,@RequestParam Instant to){return service.dashboard(from,to);}}
